    def __init__(self, values=None):
        values = values if values is not None else []
        self._head = None
        self._len = 0
        for value in values:
            self.push(value)

    def __iter__(self):
        return LinkedIterator(self)

    def __len__(self):
        return self._len

    def head(self):
        if self._head is None:
            raise EmptyListException('The list is empty.')
        return self._head

